/**
 * 计价规则匹配与计算（W13）—— 版本化、确定性、历史不重算。
 *
 * 依据：
 *   - TRD §10.1（API：cache 命中/未命中/输出分项 × 单价，按 Attempt 开始时间+资源+模型+规则版本）；
 *   - TRD §10.2（套餐：deducted_quota = raw_usage × matched_multiplier；费用字段 PACKAGE_INCLUDED）；
 *   - TRD §10.3（周期重置幂等、未用不结转）；
 *   - 调研文档「厂商额度扣减规则」：倍数不写死，按资源当期生效规则版本匹配；
 *     智谱分时（14:00–18:00 UTC+8 高峰 3 倍/非高峰 2 倍）、Kimi 模型档位（highspeed 3 倍）。
 *
 * 确定性（工程规则 §7）：同输入同输出；时钟由调用方注入（attemptStartedAt）。
 * 金额：decimal.js 十进制，避免浮点精度损失；输出字符串（PostgreSQL numeric）。
 */
import { Decimal } from "decimal.js";

// ===== 规则形状（与 0011 billing_rule 表对应）=====

export const BILLING_RULE_TYPE_W13 = {
  TIME_WINDOW: "TIME_WINDOW", // 分时倍率（智谱高峰）
  MODEL_TIER: "MODEL_TIER", // 模型档位倍率（Kimi highspeed）
  CACHE_STATE: "CACHE_STATE", // 缓存状态价格（DeepSeek 预留）
  API_PRICE: "API_PRICE", // Token 单价
} as const;

export interface BillingRuleWindow {
  timezone: string;
  daysOfWeek: number[] | null; // ISO 1=周一..7=周日；null=每天
  startTime: string; // "HH:MM" 或 "HH:MM:SS"
  endTime: string;
}

export interface BillingRule {
  id: string;
  ruleType: "TIME_WINDOW" | "MODEL_TIER" | "CACHE_STATE" | "API_PRICE";
  ruleVersion: string;
  providerResourceId: string | null; // null = 企业级默认
  upstreamModel: string | null; // null = 全部模型
  effectiveFrom: number; // epoch ms
  effectiveTo: number | null;
  timezone: string | null;
  daysOfWeek: number[] | null; // ISO 1=周一..7=周日；null=每天
  startTime: string | null; // "HH:MM" 或 "HH:MM:SS"
  endTime: string | null;
  /** POOL-001：有序多时间窗；旧数据为空时回退到上面的单窗字段。 */
  timeWindows: BillingRuleWindow[] | null;
  multiplier: string | null; // decimal 字符串
  cacheHitPrice: string | null;
  cacheMissPrice: string | null;
  outputPrice: string | null;
  currency: string;
  priority: number; // 数值小优先
}

/** 匹配结果（冻结到 ledger_line）。 */
export interface RuleMatch {
  ruleId: string;
  ruleVersion: string;
  /** 套餐扣减倍率（无倍数规则时 "1"）。 */
  multiplier: string;
  /** 命中的完整规则，用于把结算事实冻结到账本快照。 */
  rule: BillingRule;
  /** 实际命中的窗口；MODEL_TIER 等无窗口规则为 null。 */
  matchedWindow: BillingRuleWindow | null;
}

// ===== 时段判定（确定性，注入时钟）=====

/** 把 epoch ms 转成指定时区的「星期 + HH:MM:SS」。仅用 Intl，无外部依赖，可回放。 */
export function toZonedTime(
  epochMs: number,
  timezone: string,
): { dayOfWeek: number; minutesOfDay: number; secondsOfDay: number } {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });
  const parts = fmt.formatToParts(new Date(epochMs));
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  const dowMap: Record<string, number> = { Sun: 7, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  const dayOfWeek = dowMap[get("weekday")] ?? 1;
  let hour = parseInt(get("hour"), 10);
  if (hour === 24) hour = 0; // Intl hour12:false 偶尔给 24
  const minutesOfDay = hour * 60 + parseInt(get("minute"), 10);
  const secondsOfDay = minutesOfDay * 60 + parseInt(get("second"), 10);
  return { dayOfWeek, minutesOfDay, secondsOfDay };
}

function parseTimeSeconds(s: string): number {
  const [h = "0", m = "0", second = "0"] = s.split(":");
  return parseInt(h, 10) * 3600 + parseInt(m, 10) * 60 + parseInt(second, 10);
}

/** 兼容旧单窗列：新数组优先，旧数据自动投影成单元素数组。 */
export function configuredTimeWindows(rule: BillingRule): BillingRuleWindow[] {
  if (rule.timeWindows && rule.timeWindows.length > 0) return rule.timeWindows;
  if (!rule.timezone || !rule.startTime || !rule.endTime) return [];
  return [{
    timezone: rule.timezone,
    daysOfWeek: rule.daysOfWeek,
    startTime: rule.startTime,
    endTime: rule.endTime,
  }];
}

function matchesWindow(window: BillingRuleWindow, epochMs: number): boolean {
  const { dayOfWeek, secondsOfDay } = toZonedTime(epochMs, window.timezone);
  const start = parseTimeSeconds(window.startTime);
  const end = parseTimeSeconds(window.endTime);
  if (start <= end) {
    if (window.daysOfWeek && !window.daysOfWeek.includes(dayOfWeek)) return false;
    return secondsOfDay >= start && secondsOfDay < end;
  }

  // 跨午夜窗口的星期归属开始日：例如“周一 23:00–02:00”包含周二 01:00。
  // 结束日凌晨段要用前一天判断，避免要求管理员同时勾选周二而产生歧义。
  const startDay = secondsOfDay >= start
    ? dayOfWeek
    : dayOfWeek === 1
      ? 7
      : dayOfWeek - 1;
  if (window.daysOfWeek && !window.daysOfWeek.includes(startDay)) return false;
  return secondsOfDay >= start || secondsOfDay < end;
}

/**
 * 返回实际命中的窗口。多个窗口重叠时按配置数组顺序取第一个；
 * 同一规则内单价/倍率相同，顺序只用于账本解释保持确定性。
 */
export function findMatchedTimeWindow(
  rule: BillingRule,
  epochMs: number,
): BillingRuleWindow | null {
  return configuredTimeWindows(rule).find((window) => matchesWindow(window, epochMs)) ?? null;
}

/** 时段规则是否命中（任一窗口；边界 [start,end)，支持跨午夜）。 */
export function matchesTimeWindow(rule: BillingRule, epochMs: number): boolean {
  return findMatchedTimeWindow(rule, epochMs) !== null;
}

function scopeSpecificity(rule: BillingRule): number {
  return (rule.providerResourceId !== null ? 2 : 0) + (rule.upstreamModel !== null ? 1 : 0);
}

/**
 * 所有计价规则共用的确定性顺序：
 * priority（小优先）→ 资源/模型特异性 → 时窗特异性 → 较新生效版本 → id。
 *
 * 最后以 id 兜底，保证即使管理员配置了完全重叠的同优先级规则，同一输入仍唯一命中。
 */
function compareRulePrecedence(a: BillingRule, b: BillingRule): number {
  if (a.priority !== b.priority) return a.priority - b.priority;
  const scope = scopeSpecificity(b) - scopeSpecificity(a);
  if (scope !== 0) return scope;
  const timeWindow = Number(configuredTimeWindows(b).length > 0)
    - Number(configuredTimeWindows(a).length > 0);
  if (timeWindow !== 0) return timeWindow;
  if (a.effectiveFrom !== b.effectiveFrom) return b.effectiveFrom - a.effectiveFrom;
  return a.id.localeCompare(b.id);
}

/**
 * 匹配套餐扣减倍率规则。
 * 候选顺序：优先级（数值小优先）→ 资源专属优先于企业默认 → 模型专属优先于全部模型。
 * 返回命中的最高优先级倍率；无规则时 multiplier="1"（原始口径，不折算）。
 */
export function matchMultiplierRule(
  rules: BillingRule[],
  resourceId: string,
  upstreamModel: string,
  attemptStartedAt: number,
): RuleMatch | null {
  const candidates = rules
    .filter((r) => {
      if (r.ruleType !== "TIME_WINDOW" && r.ruleType !== "MODEL_TIER") return false;
      if (r.providerResourceId !== null && r.providerResourceId !== resourceId) return false;
      if (r.upstreamModel !== null && r.upstreamModel !== upstreamModel) return false;
      if (attemptStartedAt < r.effectiveFrom) return false;
      if (r.effectiveTo !== null && attemptStartedAt >= r.effectiveTo) return false;
      if (r.ruleType === "TIME_WINDOW") return matchesTimeWindow(r, attemptStartedAt);
      return true; // MODEL_TIER 只按模型匹配
    })
    .sort(compareRulePrecedence);
  const hit = candidates[0];
  if (!hit || hit.multiplier === null) return null;
  return {
    ruleId: hit.id,
    ruleVersion: hit.ruleVersion,
    multiplier: hit.multiplier,
    rule: hit,
    matchedWindow: hit.ruleType === "TIME_WINDOW"
      ? findMatchedTimeWindow(hit, attemptStartedAt)
      : null,
  };
}

// ===== 计算 =====

/** 套餐扣减：raw_usage × multiplier（decimal 精度，整数 token）。 */
export function computeDeductedQuota(rawUsage: number, multiplier: string): string {
  return new Decimal(rawUsage).times(new Decimal(multiplier)).toFixed(0);
}

/**
 * API 计价（TRD §10.1）：
 *   api_cost = cache_hit_input × hit_price + cache_miss_input × miss_price + output × output_price
 * cache = cache 命中 input；cache_miss_input = input - cache。
 * 价格取匹配到的 API_PRICE 规则（缺失分项按 0 处理）。
 */
export function computeApiCostFromRule(
  rule: { cacheHitPrice: string | null; cacheMissPrice: string | null; outputPrice: string | null },
  input: number,
  output: number,
  cache: number,
): string {
  const hit = new Decimal(cache);
  const miss = new Decimal(input).minus(hit);
  const cost = hit
    .times(new Decimal(rule.cacheHitPrice ?? "0"))
    .plus(miss.times(new Decimal(rule.cacheMissPrice ?? "0")))
    .plus(new Decimal(output).times(new Decimal(rule.outputPrice ?? "0")));
  return cost.toFixed(8);
}

/** 匹配套餐/API 价格规则（API_PRICE 类型，按生效版本）。 */
export function matchPriceRule(
  rules: BillingRule[],
  resourceId: string,
  upstreamModel: string,
  attemptStartedAt: number,
): BillingRule | null {
  const candidates = rules
    .filter((r) => {
      if (r.ruleType !== "API_PRICE") return false;
      if (r.providerResourceId !== null && r.providerResourceId !== resourceId) return false;
      if (r.upstreamModel !== null && r.upstreamModel !== upstreamModel) return false;
      if (attemptStartedAt < r.effectiveFrom) return false;
      if (r.effectiveTo !== null && attemptStartedAt >= r.effectiveTo) return false;
      const hasWindow = configuredTimeWindows(r).length > 0;
      if (hasWindow && !matchesTimeWindow(r, attemptStartedAt)) return false;
      return true;
    })
    .sort(compareRulePrecedence);
  return candidates[0] ?? null;
}

/** 套餐模式费用字段语义（TRD §10.2：PACKAGE_INCLUDED，不写数值 0）。 */
export const PACKAGE_INCLUDED = "PACKAGE_INCLUDED" as const;

src/dispatch-policy.ts.source:
/**
 * 经营调度（W16）—— 峰谷/成本/额度/周期策略匹配 + 动作判定 + 反事实节省（纯函数，确定性）。
 *
 * 依据：TRD §9.1 行 609-632（经营调度叠加）、§5.6 行 314-321（dispatch_policy_version）、
 * §5.7 行 342（dispatch_decision 不可覆盖）。
 *
 *   技术路由（W12）生成"能调用"的候选；经营调度（W16）决定"现在应该调用谁以及是否应该放行"：
 *   1. 以请求开始时间和企业时区命中价格/倍率版本（行 613）；
 *   2. 读取候选资源剩余额度、周期结束时间、预计耗尽时间和预测可信度（行 614）；
 *   3. 过滤不满足主体额度、成本边界或已发布调度策略的候选（行 615）；
 *   4. 只在 equivalent_resource_group 内执行自动 SWITCH（行 616）；
 *   5. 执行 ALLOW/SWITCH/RATE_LIMIT/REJECT/ALLOW_OVERAGE（行 617）；
 *   6. 冻结 dispatch_decision，后续配置变化不得改写本次理由（行 618）。
 *
 * 节省（行 620-632）：
 *   dispatch_saving = counterfactual_cost_of_published_baseline − actual_cost_after_executed_action
 *   - 反事实基线必须来自同一请求时点、已发布策略和可调用候选；
 *   - 只有动作实际执行并有价格/倍率证据时才落 dispatch_saving；
 *   - 仅提示、用户没有改变行为或基线不可比时标记 NOT_CALCULABLE；
 *   - 节省是经营分析派生值，不修改上游真实费用和 Token 用量事实。
 *
 * 确定性（工程规则 §7）：同输入同输出，时钟注入，无随机，可回放。
 */
import { toZonedTime } from "./billing-rule.js";

/** 经营调度策略版本（W16 冻结；调整需 Planning Change）。 */
export const DISPATCH_POLICY_VERSION = "w16-v1" as const;

/** 决策原因码（dispatch_decision.reason_code 稳定枚举，机器可读）。 */
export const DISPATCH_REASON = {
  ALLOW_NO_POLICY: "ALLOW_NO_POLICY", // 无命中策略，默认放行
  ALLOW_MATCHED: "ALLOW_MATCHED", // 命中 ALLOW 策略
  SWITCH_WITHIN_GROUP: "SWITCH_WITHIN_GROUP", // 命中 SWITCH 且目标在等价组内
  SWITCH_TARGET_NOT_IN_GROUP: "SWITCH_TARGET_NOT_IN_GROUP", // 目标不在等价组 → 降级 ALLOW（不可越界切换）
  SWITCH_NO_TARGET: "SWITCH_NO_TARGET", // 等价组无其他可用目标 → 降级 ALLOW
  RATE_LIMITED: "RATE_LIMITED", // 命中限流
  REJECTED: "REJECTED", // 命中拒绝
  ALLOW_OVERAGE_MATCHED: "ALLOW_OVERAGE_MATCHED", // 命中允许超额
} as const;

export type DispatchReason = (typeof DISPATCH_REASON)[keyof typeof DISPATCH_REASON];

/** 等价资源组（SWITCH 仅在此组内执行，TRD §9.1 行 616）。 */
export type EquivalentResourceGroup = readonly string[];

/** 管理员发布的经营调度策略（PUBLISHED 状态进入热路径）。 */
export interface DispatchPolicy {
  id: string;
  /** 策略状态（仅 PUBLISHED 参与 matching）。 */
  status: "DRAFT" | "VALIDATED" | "PUBLISHED" | "RETIRED";
  // 匹配条件（nullable = 不限）
  matchUnifiedModel: string | null;
  matchResourceMode: "API" | "CODING_PLAN" | null;
  matchProviderResourceId: string | null;
  matchTimezone: string | null;
  matchDaysOfWeek: number[] | null;
  matchStartTime: string | null; // HH:mm:ss
  matchEndTime: string | null;
  /** 价格倍率下限（≥；用于命中高峰：当请求时点价格倍率 ≥ 此值时匹配）。 */
  matchPriceMultiplierMin: string | null;
  /** 剩余额度比例上限（≤；用于耗尽风险：remaining/quota ≤ 此值时匹配）。 */
  matchRemainingQuotaRatioMax: string | null;
  /** 仅当预计耗尽风险为真时匹配（forecastExhaustAt 在周期内）。 */
  matchForecastExhaustRisk: boolean | null;
  /** 主体范围（principalId 列表；null/空 = 任意主体）。 */
  matchPrincipalScope: string[] | null;
  // 动作
  action: "ALLOW" | "SWITCH" | "RATE_LIMIT" | "REJECT" | "ALLOW_OVERAGE";
  /** SWITCH 专用：可切换的等价资源组。 */
  switchEquivalentGroup: EquivalentResourceGroup;
  /** RATE_LIMIT 专用：每分钟限流数（null=仅标记限流，不计具体数）。 */
  rateLimitPerMinute: number | null;
  // 版本
  policyVersion: string;
  /** 优先级（数值小优先；同请求多命中时取最高优先级）。 */
  priority: number;
}

/** 请求时经营输入快照（冻结到 dispatch_decision.dispatch_input）。 */
export interface DispatchInput {
  /** 请求开始时间（epoch ms，注入）。 */
  now: number;
  /** 统一模型别名。 */
  unifiedModel: string;
  /** 评分选中的资源 ID（技术路由 winner）。 */
  selectedResourceId: string;
  /** 资源模式。 */
  resourceMode: "API" | "CODING_PLAN";
  /** 该请求时点命中的价格倍率（来自 W13 billing_rule；无规则="1"）。 */
  priceMultiplier: string;
  /** 剩余额度比例（remaining/quota，0..1；未知=null）。 */
  remainingQuotaRatio: number | null;
  /** 预计耗尽是否在周期内（来自 W15 forecast；true=有耗尽风险）。 */
  forecastExhaustRisk: boolean;
  /** 主体 ID。 */
  principalId: string;
}

/** 决策结果。 */
export interface DispatchDecision {
  /** 命中的最高优先级策略（无则 null → 默认 ALLOW）。 */
  matchedPolicy: DispatchPolicy | null;
  /** 最终动作（结合硬约束：SWITCH 越界/无目标时降级 ALLOW）。 */
  finalAction: "ALLOW" | "SWITCH" | "RATE_LIMIT" | "REJECT" | "ALLOW_OVERAGE";
  /** 原因码。 */
  reasonCode: DispatchReason;
  /** SWITCH 时的目标资源（等价组内；非 SWITCH 动作为 null）。 */
  switchTargetResourceId: string | null;
}

/**
 * 单条策略是否匹配请求输入（TRD §9.1 行 613-617）。
 * 任一匹配条件不满足即不匹配；nullable 条件 = 不限。
 */
export function matchPolicy(policy: DispatchPolicy, input: DispatchInput): boolean {
  if (policy.status !== "PUBLISHED") return false; // 只有 PUBLISHED 进热路径（§5.6 行 320）

  // 统一模型
  if (policy.matchUnifiedModel !== null && policy.matchUnifiedModel !== input.unifiedModel) return false;
  // 资源模式
  if (policy.matchResourceMode !== null && policy.matchResourceMode !== input.resourceMode) return false;
  // 指定资源
  if (policy.matchProviderResourceId !== null && policy.matchProviderResourceId !== input.selectedResourceId) return false;
  // 主体范围
  if (
    policy.matchPrincipalScope !== null &&
    policy.matchPrincipalScope.length > 0 &&
    !policy.matchPrincipalScope.includes(input.principalId)
  ) {
    return false;
  }
  // 时间窗（星期 + 起止时间，复用 W13 时区逻辑）
  if (policy.matchTimezone && policy.matchStartTime && policy.matchEndTime) {
    if (!matchTimeWindowInternal(policy, input.now)) return false;
  }
  // 价格倍率下限（≥）
  if (policy.matchPriceMultiplierMin !== null) {
    if (compareDecimal(input.priceMultiplier, policy.matchPriceMultiplierMin) < 0) return false;
  }
  // 剩余额度比例上限（≤）
  if (policy.matchRemainingQuotaRatioMax !== null) {
    if (input.remainingQuotaRatio === null) return false; // 未知额度不命中耗尽风险类策略（不伪精确）
    if (input.remainingQuotaRatio > Number(policy.matchRemainingQuotaRatioMax)) return false;
  }
  // 预计耗尽风险（仅当 input 标记有风险时匹配）
  if (policy.matchForecastExhaustRisk === true && !input.forecastExhaustRisk) return false;

  return true;
}

/** 时间窗匹配（内部复用 billing-rule.toZonedTime，支持跨午夜）。 */
function matchTimeWindowInternal(policy: DispatchPolicy, epochMs: number): boolean {
  const { dayOfWeek, secondsOfDay } = toZonedTime(epochMs, policy.matchTimezone!);
  if (policy.matchDaysOfWeek && policy.matchDaysOfWeek.length > 0 && !policy.matchDaysOfWeek.includes(dayOfWeek)) {
    return false;
  }
  const start = parseTimeSeconds(policy.matchStartTime!);
  const end = parseTimeSeconds(policy.matchEndTime!);
  if (start < end) return secondsOfDay >= start && secondsOfDay < end;
  return secondsOfDay >= start || secondsOfDay < end; // 跨午夜
}

function parseTimeSeconds(s: string): number {
  const [h = "0", m = "0", second = "0"] = s.split(":");
  return parseInt(h, 10) * 3600 + parseInt(m, 10) * 60 + parseInt(second, 10);
}

/** decimal 字符串比较（>0 表示 a>b；避免 number 精度）。 */
function compareDecimal(a: string, b: string): number {
  const da = Number(a);
  const db = Number(b);
  if (Number.isNaN(da) || Number.isNaN(db)) return 0;
  return da < db ? -1 : da > db ? 1 : 0;
}

/**
 * 经营调度判定（TRD §9.1 行 611-618）。
 *
 * 流程：
 *   1. 从已发布策略中找出所有匹配的，取最高优先级（priority 数值最小）；
 *   2. 无匹配 → 默认 ALLOW_NO_POLICY；
 *   3. 命中 SWITCH：
 *      - 目标必须在等价组内（行 616），否则降级 ALLOW（不越界）；
 *      - 等价组无其他可用候选 → 降级 ALLOW；
 *   4. 其他动作原样执行。
 *
 * @param policies  该企业已发布的全部策略（热路径查询后传入）
 * @param input     请求时经营输入
 * @param availableResourceIds  当前可调用候选（SWITCH 目标必须在此 ∩ 等价组内）
 */
export function decideDispatch(
  policies: readonly DispatchPolicy[],
  input: DispatchInput,
  availableResourceIds: ReadonlySet<string>,
): DispatchDecision {
  const matched = policies
    .filter((p) => matchPolicy(p, input))
    .sort((a, b) => a.priority - b.priority || a.id.localeCompare(b.id));

  if (matched.length === 0) {
    return {
      matchedPolicy: null,
      finalAction: "ALLOW",
      reasonCode: DISPATCH_REASON.ALLOW_NO_POLICY,
      switchTargetResourceId: null,
    };
  }

  const policy = matched[0]!;

  switch (policy.action) {
    case "SWITCH": {
      // 目标 = 等价组内 ∩ 可用候选，排除当前选中资源
      const targets = policy.switchEquivalentGroup.filter(
        (rid) => rid !== input.selectedResourceId && availableResourceIds.has(rid),
      );
      if (targets.length === 0) {
        // 等价组无可用目标 → 降级 ALLOW（不无账放行）
        return {
          matchedPolicy: policy,
          finalAction: "ALLOW",
          reasonCode: DISPATCH_REASON.SWITCH_NO_TARGET,
          switchTargetResourceId: null,
        };
      }
      const target = targets[0]!;
      // 目标必须在等价组内（防御：availableResourceIds 已过滤，此处再确认）
      if (!policy.switchEquivalentGroup.includes(target)) {
        return {
          matchedPolicy: policy,
          finalAction: "ALLOW",
          reasonCode: DISPATCH_REASON.SWITCH_TARGET_NOT_IN_GROUP,
          switchTargetResourceId: null,
        };
      }
      return {
        matchedPolicy: policy,
        finalAction: "SWITCH",
        reasonCode: DISPATCH_REASON.SWITCH_WITHIN_GROUP,
        switchTargetResourceId: target,
      };
    }
    case "RATE_LIMIT":
      return { matchedPolicy: policy, finalAction: "RATE_LIMIT", reasonCode: DISPATCH_REASON.RATE_LIMITED, switchTargetResourceId: null };
    case "REJECT":
      return { matchedPolicy: policy, finalAction: "REJECT", reasonCode: DISPATCH_REASON.REJECTED, switchTargetResourceId: null };
    case "ALLOW_OVERAGE":
      return { matchedPolicy: policy, finalAction: "ALLOW_OVERAGE", reasonCode: DISPATCH_REASON.ALLOW_OVERAGE_MATCHED, switchTargetResourceId: null };
    case "ALLOW":
    default:
      return { matchedPolicy: policy, finalAction: "ALLOW", reasonCode: DISPATCH_REASON.ALLOW_MATCHED, switchTargetResourceId: null };
  }
}

/**
 * 计算反事实节省（TRD §9.1 行 620-632）。
 *
 *   dispatch_saving = counterfactual_cost_of_published_baseline − actual_cost_after_executed_action
 *
 * 标记 NOT_CALCULABLE 的条件（行 631）：
 *   - 仅提示（finalAction=ALLOW 但用户行为未改变 / RATE_LIMIT 未实际拒绝）；
 *   - 反事实基线不可比（counterfactualCost=null 或 actualCost=null）；
 *   - 无价格/倍率证据（行 630）。
 *
 * @returns saving：可计算时为 8 位小数（可负）；不可计算时为 "NOT_CALCULABLE"。
 */
export function computeDispatchSaving(input: {
  finalAction: "ALLOW" | "SWITCH" | "RATE_LIMIT" | "REJECT" | "ALLOW_OVERAGE";
  /** 反事实基线成本（若选用评分 winner 的预期成本）。 */
  counterfactualCost: string | null;
  /** 实际执行后的成本（decimal 字符串）。 */
  actualCost: string | null;
  /** 动作是否实际执行并改变了资源/行为（SWITCH 实际切换=true；仅提示=false）。 */
  actionExecuted: boolean;
}): { saving: string | "NOT_CALCULABLE"; reason: string | null } {
  // 仅提示、用户没有改变行为 → NOT_CALCULABLE（行 631）
  if (!input.actionExecuted) {
    return { saving: "NOT_CALCULABLE", reason: "no_action_executed" };
  }
  // 基线不可比 → NOT_CALCULABLE（行 628, 631）
  if (input.counterfactualCost === null || input.actualCost === null) {
    return { saving: "NOT_CALCULABLE", reason: "baseline_not_comparable" };
  }
  const cf = decimalToScaled(input.counterfactualCost, 8);
  const actual = decimalToScaled(input.actualCost, 8);
  if (cf === null || actual === null) {
    return { saving: "NOT_CALCULABLE", reason: "invalid_cost_value" };
  }
  // 节省 = 反事实 − 实际（可正可负；可负表示实际更贵）
  return { saving: scaledToDecimal(cf - actual, 8), reason: null };
}

function decimalToScaled(value: string, scale: number): bigint | null {
  const match = /^(-?)(\d+)(?:\.(\d+))?$/.exec(value.trim());
  if (!match) return null;
  const fraction = match[3] ?? "";
  if (fraction.length > scale) return null;
  const scaled = BigInt(match[2]!) * 10n ** BigInt(scale) + BigInt(fraction.padEnd(scale, "0"));
  return match[1] === "-" ? -scaled : scaled;
}

function scaledToDecimal(value: bigint, scale: number): string {
  const negative = value < 0n;
  const absolute = negative ? -value : value;
  const factor = 10n ** BigInt(scale);
  const integer = absolute / factor;
  const fraction = (absolute % factor).toString().padStart(scale, "0");
  return `${negative ? "-" : ""}${integer}.${fraction}`;
}

src/quota-gate.ts.source:
/**
 * 额度门禁（W14）—— 主体额度判定（纯函数，确定性）。
 *
 * 依据：TRD §5.5（principal_grant / quota_counter）、§9 行 600-607（停止条件）。
 *   - 主体额度耗尽且不允许超额 → REJECT（停止）；
 *   - allow_overage=true → 耗尽后 ALLOW_OVERAGE（产生超额记录）；
 *   - 额度按 deducted_quota（W13 倍率折算后）扣减，不是 raw。
 *
 * 热路径流程（real-pipeline 步骤 3b 前）：
 *   1. evaluateQuotaGate：判定 ALLOW / ALLOW_OVERAGE / REJECT；
 *   2. ALLOW → 预占（quota_counter.used += estimated）；
 *   3. Attempt 后按实际 deducted_quota 校正（多退少补）。
 *
 * 确定性：同输入同输出；时钟注入。金额/token 用 bigint（整数 token）。
 */

/** 门禁判定结果。 */
export const QUOTA_DECISION = {
  ALLOW: "ALLOW", // 额度充足
  ALLOW_OVERAGE: "ALLOW_OVERAGE", // 超额但允许（记录超额）
  REJECT_EXHAUSTED: "REJECT_EXHAUSTED", // 耗尽且不允许超额
  REJECT_NO_GRANT: "REJECT_NO_GRANT", // 无有效授权
  REJECT_GRANT_EXPIRED: "REJECT_GRANT_EXPIRED", // 授权过期/停用
} as const;

export type QuotaDecision = (typeof QUOTA_DECISION)[keyof typeof QUOTA_DECISION];

export interface QuotaGateInput {
  /** 是否存在有效授权（principal_grant）。 */
  hasGrant: boolean;
  /** 授权状态（ACTIVE/EXPIRED/DISABLED）。 */
  grantStatus: "ACTIVE" | "EXPIRED" | "DISABLED" | null;
  /** 授权有效期。 */
  validFrom: number | null;
  validUntil: number | null;
  /** 额度总量（quota_value）。 */
  quotaValue: bigint;
  /** 当前周期已用（quota_counter.used_value）。 */
  usedValue: bigint;
  /** 本请求预估扣减（deducted_quota 预估；结算时按实际校正）。 */
  estimatedCost: bigint;
  /** 是否允许超额。 */
  allowOverage: boolean;
  /** 当前时间（epoch ms，注入）。 */
  now: number;
}

export interface QuotaGateResult {
  decision: QuotaDecision;
  /** 放行后的预计剩余（REJECT 时为当前剩余）。 */
  projectedRemaining: bigint;
  /** 是否产生超额（ALLOW_OVERAGE 时超出部分）。 */
  overageAmount: bigint;
}

/** 额度门禁判定。 */
export function evaluateQuotaGate(input: QuotaGateInput): QuotaGateResult {
  if (!input.hasGrant) {
    return { decision: QUOTA_DECISION.REJECT_NO_GRANT, projectedRemaining: 0n, overageAmount: 0n };
  }
  if (input.grantStatus !== "ACTIVE") {
    return { decision: QUOTA_DECISION.REJECT_GRANT_EXPIRED, projectedRemaining: 0n, overageAmount: 0n };
  }
  if (input.validFrom !== null && input.now < input.validFrom) {
    return { decision: QUOTA_DECISION.REJECT_GRANT_EXPIRED, projectedRemaining: 0n, overageAmount: 0n };
  }
  if (input.validUntil !== null && input.now >= input.validUntil) {
    return { decision: QUOTA_DECISION.REJECT_GRANT_EXPIRED, projectedRemaining: 0n, overageAmount: 0n };
  }

  const remaining = input.quotaValue - input.usedValue;
  const projectedRemaining = remaining - input.estimatedCost;

  if (projectedRemaining >= 0n) {
    return { decision: QUOTA_DECISION.ALLOW, projectedRemaining, overageAmount: 0n };
  }
  // 耗尽
  if (input.allowOverage) {
    return {
      decision: QUOTA_DECISION.ALLOW_OVERAGE,
      projectedRemaining,
      overageAmount: -projectedRemaining, // 超出部分
    };
  }
  return { decision: QUOTA_DECISION.REJECT_EXHAUSTED, projectedRemaining: remaining, overageAmount: 0n };
}

/**
 * 结算校正：预占 estimated，实际 actual。
 * 返回 quota_counter 应有的新 used_value（多退少补，不为负）。
 */
export function settleQuota(usedAfterReserve: bigint, estimated: bigint, actual: bigint): bigint {
  const corrected = usedAfterReserve - estimated + actual;
  return corrected < 0n ? 0n : corrected;
}

