/**
 * W16 单元测试：经营调度（matchPolicy / decideDispatch / computeDispatchSaving）。
 *
 * 覆盖：
 *   - matchPolicy：各匹配条件（模型/资源/模式/主体/时间窗/价格倍率/额度比例/耗尽风险）
 *   - decideDispatch：无策略默认 ALLOW；命中各动作；SWITCH 越界/无目标降级
 *   - computeDispatchSaving：可计算/NOT_CALCULABLE 各原因（行 628-632）
 *
 * 依据：TRD §9.1 行 609-632；WT-16/17。
 * 风格对齐 quota-gate.test.ts：注入时钟 T0，工厂函数，边界 case。
 */
import { describe, it, expect } from "vitest";
import {
  matchPolicy,
  decideDispatch,
  computeDispatchSaving,
  DISPATCH_REASON,
  DISPATCH_POLICY_VERSION,
  type DispatchPolicy,
  type DispatchInput,
} from "../index.js";

// 2026-07-27 15:30:00 UTC+8（周一 15:30，落在 14:00-18:00 高峰窗内）
const T0 = Date.UTC(2026, 6, 27, 7, 30, 0);
const RES_A = "res-a";
const RES_B = "res-b";
const RES_C = "res-c";
const PRINCIPAL = "principal-1";

function policy(overrides: Partial<DispatchPolicy> = {}): DispatchPolicy {
  return {
    id: "pol-1",
    status: "PUBLISHED",
    matchUnifiedModel: null,
    matchResourceMode: null,
    matchProviderResourceId: null,
    matchTimezone: null,
    matchDaysOfWeek: null,
    matchStartTime: null,
    matchEndTime: null,
    matchPriceMultiplierMin: null,
    matchRemainingQuotaRatioMax: null,
    matchForecastExhaustRisk: null,
    matchPrincipalScope: null,
    action: "ALLOW",
    switchEquivalentGroup: [],
    rateLimitPerMinute: null,
    policyVersion: DISPATCH_POLICY_VERSION,
    priority: 100,
    ...overrides,
  };
}

function input(overrides: Partial<DispatchInput> = {}): DispatchInput {
  return {
    now: T0,
    unifiedModel: "qianliu-glm-coding",
    selectedResourceId: RES_A,
    resourceMode: "CODING_PLAN",
    priceMultiplier: "1",
    remainingQuotaRatio: null,
    forecastExhaustRisk: false,
    principalId: PRINCIPAL,
    ...overrides,
  };
}

describe("matchPolicy 匹配条件", () => {
  it("非 PUBLISHED 状态不匹配（只有 PUBLISHED 进热路径）", () => {
    expect(matchPolicy(policy({ status: "DRAFT" }), input())).toBe(false);
    expect(matchPolicy(policy({ status: "RETIRED" }), input())).toBe(false);
  });

  it("PUBLISHED 且无条件 → 匹配（通配策略）", () => {
    expect(matchPolicy(policy(), input())).toBe(true);
  });

  it("统一模型不匹配 → false", () => {
    expect(matchPolicy(policy({ matchUnifiedModel: "qianliu-kimi-k3" }), input())).toBe(false);
    expect(matchPolicy(policy({ matchUnifiedModel: "qianliu-glm-coding" }), input())).toBe(true);
  });

  it("资源模式不匹配 → false", () => {
    expect(matchPolicy(policy({ matchResourceMode: "API" }), input())).toBe(false);
    expect(matchPolicy(policy({ matchResourceMode: "CODING_PLAN" }), input())).toBe(true);
  });

  it("指定资源不匹配 → false", () => {
    expect(matchPolicy(policy({ matchProviderResourceId: RES_B }), input())).toBe(false);
    expect(matchPolicy(policy({ matchProviderResourceId: RES_A }), input())).toBe(true);
  });

  it("主体范围不匹配 → false（null/空=任意）", () => {
    expect(matchPolicy(policy({ matchPrincipalScope: ["other"] }), input())).toBe(false);
    expect(matchPolicy(policy({ matchPrincipalScope: [PRINCIPAL] }), input())).toBe(true);
    expect(matchPolicy(policy({ matchPrincipalScope: null }), input())).toBe(true);
    expect(matchPolicy(policy({ matchPrincipalScope: [] }), input())).toBe(true);
  });

  it("时间窗：高峰 14:00-18:00（Asia/Shanghai）命中（WT-16 峰谷）", () => {
    const p = policy({
      matchTimezone: "Asia/Shanghai",
      matchStartTime: "14:00:00",
      matchEndTime: "18:00:00",
    });
    // T0 = UTC+8 15:30 → 命中
    expect(matchPolicy(p, input({ now: T0 }))).toBe(true);
    // 非高峰时段（UTC+8 10:00）→ 不命中
    const offPeak = Date.UTC(2026, 6, 27, 2, 0, 0); // UTC+8 10:00
    expect(matchPolicy(p, input({ now: offPeak }))).toBe(false);
  });

  it("时间窗左闭右开并精确到秒：14:00:00 命中，18:00:00 不命中", () => {
    const p = policy({
      matchTimezone: "Asia/Shanghai",
      matchStartTime: "14:00:00",
      matchEndTime: "18:00:00",
    });
    expect(matchPolicy(p, input({ now: Date.UTC(2026, 6, 27, 6, 0, 0) }))).toBe(true);
    expect(matchPolicy(p, input({ now: Date.UTC(2026, 6, 27, 9, 59, 59) }))).toBe(true);
    expect(matchPolicy(p, input({ now: Date.UTC(2026, 6, 27, 10, 0, 0) }))).toBe(false);
  });

  it("跨午夜时间窗：23:00:30–02:00:15 正确命中两侧", () => {
    const p = policy({
      matchTimezone: "Asia/Shanghai",
      matchStartTime: "23:00:30",
      matchEndTime: "02:00:15",
    });
    expect(matchPolicy(p, input({ now: Date.UTC(2026, 6, 27, 15, 0, 30) }))).toBe(true);
    expect(matchPolicy(p, input({ now: Date.UTC(2026, 6, 27, 18, 0, 14) }))).toBe(true);
    expect(matchPolicy(p, input({ now: Date.UTC(2026, 6, 27, 18, 0, 15) }))).toBe(false);
  });

  it("时间窗：星期限定（仅周一）", () => {
    const p = policy({
      matchTimezone: "Asia/Shanghai",
      matchDaysOfWeek: [1], // 周一
      matchStartTime: "00:00:00",
      matchEndTime: "23:59:59",
    });
    expect(matchPolicy(p, input({ now: T0 }))).toBe(true); // 2026-07-27 周一
    const tuesday = Date.UTC(2026, 6, 28, 7, 30, 0); // 周二
    expect(matchPolicy(p, input({ now: tuesday }))).toBe(false);
  });

  it("价格倍率下限（≥）：高峰 ×3 命中", () => {
    const p = policy({ matchPriceMultiplierMin: "3" });
    expect(matchPolicy(p, input({ priceMultiplier: "3" }))).toBe(true);
    expect(matchPolicy(p, input({ priceMultiplier: "2" }))).toBe(false);
    expect(matchPolicy(p, input({ priceMultiplier: "3.5" }))).toBe(true);
  });

  it("剩余额度比例上限（≤）：耗尽风险（WT-16 额度策略）", () => {
    const p = policy({ matchRemainingQuotaRatioMax: "0.2" }); // ≤20% 命中
    expect(matchPolicy(p, input({ remainingQuotaRatio: 0.15 }))).toBe(true);
    expect(matchPolicy(p, input({ remainingQuotaRatio: 0.25 }))).toBe(false);
    // 未知额度比例不命中耗尽风险类策略（不伪精确）
    expect(matchPolicy(p, input({ remainingQuotaRatio: null }))).toBe(false);
  });

  it("预计耗尽风险：仅当 input 标记有风险时匹配", () => {
    const p = policy({ matchForecastExhaustRisk: true });
    expect(matchPolicy(p, input({ forecastExhaustRisk: true }))).toBe(true);
    expect(matchPolicy(p, input({ forecastExhaustRisk: false }))).toBe(false);
  });
});

describe("decideDispatch 动作判定", () => {
  it("无匹配策略 → 默认 ALLOW_NO_POLICY", () => {
    const d = decideDispatch([], input(), new Set([RES_A]));
    expect(d.finalAction).toBe("ALLOW");
    expect(d.reasonCode).toBe(DISPATCH_REASON.ALLOW_NO_POLICY);
    expect(d.matchedPolicy).toBeNull();
    expect(d.switchTargetResourceId).toBeNull();
  });

  it("命中 ALLOW → ALLOW_MATCHED", () => {
    const d = decideDispatch([policy({ action: "ALLOW" })], input(), new Set([RES_A]));
    expect(d.finalAction).toBe("ALLOW");
    expect(d.reasonCode).toBe(DISPATCH_REASON.ALLOW_MATCHED);
  });

  it("命中 REJECT → REJECTED", () => {
    const d = decideDispatch([policy({ action: "REJECT" })], input(), new Set([RES_A]));
    expect(d.finalAction).toBe("REJECT");
    expect(d.reasonCode).toBe(DISPATCH_REASON.REJECTED);
  });

  it("命中 RATE_LIMIT → RATE_LIMITED", () => {
    const d = decideDispatch([policy({ action: "RATE_LIMIT", rateLimitPerMinute: 10 })], input(), new Set([RES_A]));
    expect(d.finalAction).toBe("RATE_LIMIT");
    expect(d.reasonCode).toBe(DISPATCH_REASON.RATE_LIMITED);
  });

  it("命中 ALLOW_OVERAGE", () => {
    const d = decideDispatch([policy({ action: "ALLOW_OVERAGE" })], input(), new Set([RES_A]));
    expect(d.finalAction).toBe("ALLOW_OVERAGE");
    expect(d.reasonCode).toBe(DISPATCH_REASON.ALLOW_OVERAGE_MATCHED);
  });

  it("命中 SWITCH 且目标在等价组∩可用 → SWITCH_WITHIN_GROUP（WT-16 等价切换）", () => {
    const p = policy({
      action: "SWITCH",
      switchEquivalentGroup: [RES_A, RES_B, RES_C],
    });
    const d = decideDispatch([p], input({ selectedResourceId: RES_A }), new Set([RES_A, RES_B, RES_C]));
    expect(d.finalAction).toBe("SWITCH");
    expect(d.reasonCode).toBe(DISPATCH_REASON.SWITCH_WITHIN_GROUP);
    expect(d.switchTargetResourceId).toBe(RES_B); // 等价组内第一个非当前资源
  });

  it("SWITCH：等价组内其他资源都不可用 → 降级 ALLOW_NO_TARGET（不无账放行）", () => {
    const p = policy({
      action: "SWITCH",
      switchEquivalentGroup: [RES_A, RES_B],
    });
    // 只有 RES_A 可用，RES_B 不可用
    const d = decideDispatch([p], input({ selectedResourceId: RES_A }), new Set([RES_A]));
    expect(d.finalAction).toBe("ALLOW");
    expect(d.reasonCode).toBe(DISPATCH_REASON.SWITCH_NO_TARGET);
    expect(d.switchTargetResourceId).toBeNull();
  });

  it("SWITCH：等价组只含当前资源 → 降级 ALLOW_NO_TARGET", () => {
    const p = policy({
      action: "SWITCH",
      switchEquivalentGroup: [RES_A], // 只有自己
    });
    const d = decideDispatch([p], input({ selectedResourceId: RES_A }), new Set([RES_A]));
    expect(d.finalAction).toBe("ALLOW");
    expect(d.reasonCode).toBe(DISPATCH_REASON.SWITCH_NO_TARGET);
  });

  it("多策略命中 → 取最高优先级（priority 数值最小）", () => {
    const allowP = policy({ id: "pol-allow", action: "ALLOW", priority: 200 });
    const rejectP = policy({ id: "pol-reject", action: "REJECT", priority: 50 }); // 更高优先级
    const d = decideDispatch([allowP, rejectP], input(), new Set([RES_A]));
    expect(d.finalAction).toBe("REJECT");
    expect(d.matchedPolicy?.id).toBe("pol-reject");
  });

  it("同优先级按策略 ID 稳定决胜，与数据库返回顺序无关", () => {
    const later = policy({ id: "policy-z", action: "ALLOW", priority: 50 });
    const earlier = policy({ id: "policy-a", action: "REJECT", priority: 50 });
    const first = decideDispatch([later, earlier], input(), new Set([RES_A]));
    const second = decideDispatch([earlier, later], input(), new Set([RES_A]));
    expect(first.matchedPolicy?.id).toBe("policy-a");
    expect(second.matchedPolicy?.id).toBe("policy-a");
    expect(first.finalAction).toBe("REJECT");
  });
});

describe("computeDispatchSaving 反事实节省（WT-17，§9.1 行 620-632）", () => {
  it("可计算：反事实 − 实际 = 正节省（切换到更便宜资源）", () => {
    const r = computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "0.100",
      actualCost: "0.060",
      actionExecuted: true,
    });
    expect(r.saving).toBe("0.04000000");
    expect(r.reason).toBeNull();
  });

  it("可计算：负节省（实际更贵，允许为负）", () => {
    const r = computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "0.050",
      actualCost: "0.080",
      actionExecuted: true,
    });
    expect(r.saving).toBe("-0.03000000");
  });

  it("仅提示（actionExecuted=false）→ NOT_CALCULABLE（行 631：仅提示/未改变行为）", () => {
    const r = computeDispatchSaving({
      finalAction: "ALLOW",
      counterfactualCost: "0.100",
      actualCost: "0.100",
      actionExecuted: false,
    });
    expect(r.saving).toBe("NOT_CALCULABLE");
    expect(r.reason).toBe("no_action_executed");
  });

  it("反事实基线不可比（counterfactualCost=null）→ NOT_CALCULABLE（行 628, 631）", () => {
    const r = computeDispatchSaving({
      finalAction: "ALLOW",
      counterfactualCost: null,
      actualCost: "0.060",
      actionExecuted: true,
    });
    expect(r.saving).toBe("NOT_CALCULABLE");
    expect(r.reason).toBe("baseline_not_comparable");
  });

  it("无实际成本证据（actualCost=null）→ NOT_CALCULABLE（行 630：无价格证据）", () => {
    const r = computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "0.100",
      actualCost: null,
      actionExecuted: true,
    });
    expect(r.saving).toBe("NOT_CALCULABLE");
    expect(r.reason).toBe("baseline_not_comparable");
  });

  it("成本值无效 → NOT_CALCULABLE", () => {
    const r = computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "abc",
      actualCost: "0.060",
      actionExecuted: true,
    });
    expect(r.saving).toBe("NOT_CALCULABLE");
    expect(r.reason).toBe("invalid_cost_value");
  });

  it("大额小数仍按 decimal 精确相减，不经过浮点数", () => {
    const r = computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "9007199254740993.10000000",
      actualCost: "9007199254740993.09000000",
      actionExecuted: true,
    });
    expect(r.saving).toBe("0.01000000");
  });

  it("整数、首尾空白与零节省按 8 位小数稳定归一", () => {
    expect(computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: " 2 ",
      actualCost: "1",
      actionExecuted: true,
    })).toEqual({ saving: "1.00000000", reason: null });
    expect(computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "1",
      actualCost: "1",
      actionExecuted: true,
    }).saving).toBe("0.00000000");
  });

  it("负成本输入仍按符号和小数位精确换算", () => {
    expect(computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "-1.25000000",
      actualCost: "-2.50000000",
      actionExecuted: true,
    }).saving).toBe("1.25000000");
    expect(computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "12.34567890",
      actualCost: "2.00000001",
      actionExecuted: true,
    }).saving).toBe("10.34567889");
  });

  it.each(["1.000000000", "1x", "x1", "1.", ".1"])("拒绝非规范成本 %s", (invalid) => {
    expect(computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: invalid,
      actualCost: "0",
      actionExecuted: true,
    })).toEqual({ saving: "NOT_CALCULABLE", reason: "invalid_cost_value" });
  });

  it("实际成本格式错误同样不可计算", () => {
    expect(computeDispatchSaving({
      finalAction: "SWITCH",
      counterfactualCost: "1.00000000",
      actualCost: "not-a-cost",
      actionExecuted: true,
    })).toEqual({ saving: "NOT_CALCULABLE", reason: "invalid_cost_value" });
  });
});

src/__tests__/resource-lifecycle.test.ts.source:
/**
 * W11 单元测试：资源池状态机（resource-lifecycle）纯函数。
 *
 * 覆盖：
 *   - 处置矩阵：401→CREDENTIAL_INVALID、402→EXHAUSTED、429→冷却退避、临时故障→熔断阈值
 *   - 退避计算：指数增长、封顶、确定性（同输入同输出，可回放）
 *   - 成功路径：计数清零、UNAVAILABLE 半开成功→DEGRADED（一次成功不抹趋势）
 *   - 准入门禁：ACTIVE/DEGRADED 放行、冷却中拒绝、冷却到期半开探测、终态隔离拒绝
 *   - 幂等：隔离态重复事件不重复迁移
 *   - 恢复边界：CREDENTIAL_INVALID/EXHAUSTED/EXPIRED 仅 adminRecover 可恢复
 *
 * 依据：TRD §9 行 585-598、§5.4 行 243-249；WT-07/19。
 */
import { describe, it, expect } from "vitest";
import {
  RESOURCE_STATUS,
  STATE_REASON,
  RESOURCE_POOL_POLICY,
  computeCooldownMs,
  worstResourceStatus,
  deriveResourceTransition,
  deriveSuccessTransition,
  deriveCredentialExpiry,
  deriveRefreshFailure,
  deriveAdminRecovery,
  evaluateAdmission,
  type ResourceRuntimeState,
} from "../index.js";

const T0 = 1_800_000_000_000; // 固定时钟（可回放）

function active(overrides: Partial<ResourceRuntimeState> = {}): ResourceRuntimeState {
  return { status: RESOURCE_STATUS.ACTIVE, consecutiveFailures: 0, cooldownUntil: null, ...overrides };
}

describe("computeCooldownMs 指数退避", () => {
  it("混合资源取唯一最严重状态", () => {
    expect(worstResourceStatus(["ACTIVE", "DEGRADED", "RATE_LIMITED"])).toBe("RATE_LIMITED");
    expect(worstResourceStatus(["EXHAUSTED", "CREDENTIAL_INVALID", "EXPIRED"])).toBe("CREDENTIAL_INVALID");
    expect(worstResourceStatus([])).toBe("ACTIVE");
  });
  it("指数增长且确定性", () => {
    expect(computeCooldownMs(1, 30_000, 1_800_000)).toBe(30_000);
    expect(computeCooldownMs(2, 30_000, 1_800_000)).toBe(60_000);
    expect(computeCooldownMs(3, 30_000, 1_800_000)).toBe(120_000);
    expect(computeCooldownMs(4, 30_000, 1_800_000)).toBe(240_000);
    // 同输入同输出（无随机抖动，可回放）
    expect(computeCooldownMs(3, 30_000, 1_800_000)).toBe(computeCooldownMs(3, 30_000, 1_800_000));
  });

  it("封顶 cap", () => {
    expect(computeCooldownMs(100, 30_000, 1_800_000)).toBe(1_800_000);
  });
});

describe("deriveResourceTransition 处置矩阵（TRD §9）", () => {
  it("401/403 → CREDENTIAL_INVALID 隔离（仅人工恢复）", () => {
    const t = deriveResourceTransition(active(), "UPSTREAM_CREDENTIAL_INVALID", T0);
    expect(t).not.toBeNull();
    expect(t!.toStatus).toBe(RESOURCE_STATUS.CREDENTIAL_INVALID);
    expect(t!.reason).toBe(STATE_REASON.CREDENTIAL_REJECTED);
    expect(t!.isolates).toBe(true);
    expect(t!.cooldownUntil).toBeNull();
  });

  it("402 → EXHAUSTED 隔离", () => {
    const t = deriveResourceTransition(active(), "UPSTREAM_BILLING_BLOCKED", T0);
    expect(t!.toStatus).toBe(RESOURCE_STATUS.EXHAUSTED);
    expect(t!.reason).toBe(STATE_REASON.BILLING_BLOCKED);
    expect(t!.isolates).toBe(true);
  });

  it("429 立即进入短时 RATE_LIMITED，保留 Retry-After 且同波并发去重", () => {
    const t1 = deriveResourceTransition(
      active(),
      "UPSTREAM_RATE_LIMITED",
      T0,
      { retryAfterMs: 12_000 },
    );
    expect(t1!.toStatus).toBe(RESOURCE_STATUS.RATE_LIMITED);
    expect(t1!.reason).toBe(STATE_REASON.RATE_LIMITED);
    expect(t1!.cooldownUntil).toBe(T0 + 12_000);
    expect(t1!.isolates).toBe(true);
    expect(t1!.consecutiveFailures).toBe(1);

    const cooling = active({
      status: RESOURCE_STATUS.RATE_LIMITED,
      consecutiveFailures: 1,
      cooldownUntil: T0 + 12_000,
    });
    expect(deriveResourceTransition(
      cooling,
      "UPSTREAM_RATE_LIMITED",
      T0 + 1_000,
      { retryAfterMs: 60_000 },
    )).toBeNull();

    const nextWave = deriveResourceTransition(
      cooling,
      "UPSTREAM_RATE_LIMITED",
      T0 + 12_000,
      { retryAfterMs: 2_000 },
    );
    expect(nextWave!.toStatus).toBe(RESOURCE_STATUS.RATE_LIMITED);
    expect(nextWave!.consecutiveFailures).toBe(2);
    expect(nextWave!.cooldownUntil).toBe(T0 + 14_000);
  });

  it("临时故障达到旧阈值后仍保持 DEGRADED + ALLOW", () => {
    const t1 = deriveResourceTransition(active(), "UPSTREAM_TEMPORARY", T0);
    expect(t1!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t1!.reason).toBe(STATE_REASON.PASSIVE_FAILURE);
    expect(t1!.consecutiveFailures).toBe(1);
    expect(t1!.isolates).toBe(false);

    const t2 = deriveResourceTransition(
      active({ status: RESOURCE_STATUS.DEGRADED, consecutiveFailures: RESOURCE_POOL_POLICY.failureThreshold - 1 }),
      "UPSTREAM_TEMPORARY",
      T0,
    );
    expect(t2!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t2!.reason).toBe(STATE_REASON.PASSIVE_FAILURE);
    expect(t2!.isolates).toBe(false);
    expect(t2!.cooldownUntil).toBeNull();
  });

  it("TRANSPORT_ERROR 与 UNKNOWN 只计入健康降级", () => {
    const t = deriveResourceTransition(
      active({ consecutiveFailures: RESOURCE_POOL_POLICY.failureThreshold - 1 }),
      "TRANSPORT_ERROR",
      T0,
    );
    expect(t!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t!.isolates).toBe(false);
  });

  it("客户端/能力/下游/账本错误不计入资源健康", () => {
    for (const c of ["CLIENT_INVALID", "CAPABILITY_UNSUPPORTED", "DOWNSTREAM_AUTH_OR_QUOTA", "LEDGER_FAILURE", "STREAM_INTERRUPTED_AFTER_COMMIT"] as const) {
      expect(deriveResourceTransition(active(), c, T0)).toBeNull();
    }
  });

  it("幂等：CREDENTIAL_INVALID 重复 401 不重复迁移；终态隔离忽略临时故障", () => {
    const isolated = active({ status: RESOURCE_STATUS.CREDENTIAL_INVALID, consecutiveFailures: 1 });
    expect(deriveResourceTransition(isolated, "UPSTREAM_CREDENTIAL_INVALID", T0)).toBeNull();
    expect(deriveResourceTransition(isolated, "UPSTREAM_TEMPORARY", T0)).toBeNull();
    expect(deriveResourceTransition(isolated, "UPSTREAM_RATE_LIMITED", T0)).toBeNull();
    const exhausted = active({ status: RESOURCE_STATUS.EXHAUSTED });
    expect(deriveResourceTransition(exhausted, "UPSTREAM_BILLING_BLOCKED", T0)).toBeNull();
  });
});

describe("deriveSuccessTransition 成功路径", () => {
  it("ACTIVE 无失败 → 无迁移", () => {
    expect(deriveSuccessTransition(active())).toBeNull();
  });

  it("DEGRADED 成功 → ACTIVE 清零", () => {
    const t = deriveSuccessTransition(active({ status: RESOURCE_STATUS.DEGRADED, consecutiveFailures: 2 }));
    expect(t!.toStatus).toBe(RESOURCE_STATUS.ACTIVE);
    expect(t!.consecutiveFailures).toBe(0);
    expect(t!.reason).toBe(STATE_REASON.PASSIVE_SUCCESS);
  });

  it("UNAVAILABLE 半开探测成功 → DEGRADED（一次成功不抹掉长期趋势）", () => {
    const t = deriveSuccessTransition(
      active({ status: RESOURCE_STATUS.UNAVAILABLE, consecutiveFailures: 3, cooldownUntil: T0 - 1 }),
    );
    expect(t!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t!.reason).toBe(STATE_REASON.HALF_OPEN_PROBE_OK);
    expect(t!.consecutiveFailures).toBe(0);
  });

  it("RATE_LIMITED 半开探测成功 → DEGRADED 并清除冷却", () => {
    const t = deriveSuccessTransition(
      active({ status: RESOURCE_STATUS.RATE_LIMITED, consecutiveFailures: 1, cooldownUntil: T0 - 1 }),
    );
    expect(t).toMatchObject({
      toStatus: RESOURCE_STATUS.DEGRADED,
      reason: STATE_REASON.HALF_OPEN_PROBE_OK,
      consecutiveFailures: 0,
      cooldownUntil: null,
    });
  });

  it("终态隔离资源成功被防御性忽略", () => {
    expect(deriveSuccessTransition(active({ status: RESOURCE_STATUS.CREDENTIAL_INVALID }))).toBeNull();
    expect(deriveSuccessTransition(active({ status: RESOURCE_STATUS.EXHAUSTED }))).toBeNull();
  });
});

describe("evaluateAdmission 准入门禁（硬过滤）", () => {
  it("ACTIVE / DEGRADED 放行", () => {
    expect(evaluateAdmission(active(), T0).admit).toBe(true);
    expect(evaluateAdmission(active({ status: RESOURCE_STATUS.DEGRADED }), T0).admit).toBe(true);
  });

  it("UNAVAILABLE 冷却中拒绝；冷却到期允许半开探测", () => {
    const cooling = active({ status: RESOURCE_STATUS.UNAVAILABLE, cooldownUntil: T0 + 10_000 });
    const blocked = evaluateAdmission(cooling, T0);
    expect(blocked.admit).toBe(false);
    expect(blocked.blockReason).toBe(RESOURCE_STATUS.UNAVAILABLE);

    const probe = evaluateAdmission(cooling, T0 + 10_000);
    expect(probe.admit).toBe(true);
    expect(probe.probe).toBe(true);
  });

  it("RATE_LIMITED 冷却中保留限流语义；到期允许半开探测", () => {
    const cooling = active({ status: RESOURCE_STATUS.RATE_LIMITED, cooldownUntil: T0 + 10_000 });
    expect(evaluateAdmission(cooling, T0)).toEqual({
      admit: false,
      probe: false,
      blockReason: RESOURCE_STATUS.RATE_LIMITED,
    });
    expect(evaluateAdmission(cooling, T0 + 10_000)).toEqual({
      admit: true,
      probe: true,
      blockReason: null,
    });
  });

  it("终态隔离（CREDENTIAL_INVALID/EXHAUSTED/EXPIRED）拒绝", () => {
    for (const s of [RESOURCE_STATUS.CREDENTIAL_INVALID, RESOURCE_STATUS.EXHAUSTED, RESOURCE_STATUS.EXPIRED] as const) {
      const r = evaluateAdmission(active({ status: s }), T0);
      expect(r.admit).toBe(false);
      expect(r.blockReason).toBe(s);
    }
  });
});

describe("凭证生命周期（WT-19）", () => {
  it("deriveCredentialExpiry：到期 → EXPIRED；未到期/已隔离 → 无迁移", () => {
    expect(deriveCredentialExpiry(active(), T0 + 1, T0)).toBeNull(); // 未到期
    expect(deriveCredentialExpiry(active(), null, T0)).toBeNull(); // 无过期时间（API_KEY）
    const t = deriveCredentialExpiry(active(), T0, T0);
    expect(t!.toStatus).toBe(RESOURCE_STATUS.EXPIRED);
    expect(t!.reason).toBe(STATE_REASON.CREDENTIAL_EXPIRED);
    expect(t!.isolates).toBe(true);
    // 幂等
    expect(deriveCredentialExpiry(active({ status: RESOURCE_STATUS.EXPIRED }), T0, T0 + 1)).toBeNull();
  });

  it("deriveRefreshFailure：刷新失败 → CREDENTIAL_INVALID 隔离；幂等", () => {
    const t = deriveRefreshFailure(active());
    expect(t!.toStatus).toBe(RESOURCE_STATUS.CREDENTIAL_INVALID);
    expect(t!.reason).toBe(STATE_REASON.REFRESH_FAILED);
    expect(deriveRefreshFailure(active({ status: RESOURCE_STATUS.CREDENTIAL_INVALID }))).toBeNull();
  });

  it("deriveAdminRecovery：仅隔离态可恢复，恢复到 DEGRADED（受控）", () => {
    expect(deriveAdminRecovery(active())).toBeNull(); // ACTIVE 不可"恢复"
    expect(deriveAdminRecovery(active({ status: RESOURCE_STATUS.DEGRADED }))).toBeNull();
    for (const s of [RESOURCE_STATUS.CREDENTIAL_INVALID, RESOURCE_STATUS.EXHAUSTED, RESOURCE_STATUS.EXPIRED, RESOURCE_STATUS.UNAVAILABLE] as const) {
      const t = deriveAdminRecovery(active({ status: s, consecutiveFailures: 5 }));
      expect(t!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
      expect(t!.reason).toBe(STATE_REASON.ADMIN_RECOVER);
      expect(t!.consecutiveFailures).toBe(0);
    }
  });
});

